package com.controldecortes.controller;
import com.controldecortes.dto.ApiDtos.*; import com.controldecortes.service.SettlementService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/settlements") public class SettlementController { private final SettlementService service; public SettlementController(SettlementService s){service=s;} @GetMapping public List<SettlementResponse> list(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){if(from==null||to==null)return service.recent();return service.report(from.atStartOfDay().atOffset(ZoneOffset.UTC),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC));} @PostMapping public SettlementResponse create(@Valid @RequestBody SettlementRequest r){return service.create(r);} }
